uniform sampler2D tex5;  // 0x07b0c800 256x1    1D ramp
uniform sampler2D tex6;  // 0x07930000 64x64    rim/falloff table
uniform sampler2D tex13; // 0x0791f980 32x32    display/feedback RT (dither) @ screen pos
uniform sampler2D tex14; // 0x02b90000 128x128  tonemap LUT (Y16_X16_FLOAT, .zw used)
