    vec4 h2 = vec4(0.);
    vec4 r3 = vec4(0.);
    vec4 r4 = vec4(0.);
    vec4 h3 = vec4(0.);
    vec4 r0 = vec4(0.);
    vec4 r1 = vec4(0.);
    vec4 h1 = vec4(0.);
    vec4 h7 = vec4(0.);
