    r4.z = 1.0;
    // r3.y = const16.x (=0.566935) ; const16={0.566935,1,0.433065,0}
    r3.y = 0.566935;
    // r3.z = const17.x (=0.691272) ; const17={0.691272,1,0.308728,0}
    r3.z = 0.691272;
