// fp c1f67eef0f444617 -- 15-tap separable Gaussian blur of one HDR layer.
// Ported VERBATIM from fs_main. Fragment const[] inlined as numeric literals.
// Tap UVs come from the VP as varyings (centerUV +/- K*step).
//   uv0c            = tc0.xy  (center)
//   uvK_p / uvK_m   = tcK.xy / tcK.zw  (= centerUV + K*step / - K*step), K=1..7
// All taps sample tex0 (the 512x256 HDR work/glow layer at 0x02360000).
#version 430
uniform sampler2D tex0;
in vec2 uv0c;            // tc0.xy  center
in vec2 uv1_p; in vec2 uv1_m;   // tc1.xy / tc1.zw
in vec2 uv2_p; in vec2 uv2_m;   // tc2
in vec2 uv3_p; in vec2 uv3_m;   // tc3
in vec2 uv4_p; in vec2 uv4_m;   // tc4
in vec2 uv5_p; in vec2 uv5_m;   // tc5
in vec2 uv6_p; in vec2 uv6_m;   // tc6
in vec2 uv7_p; in vec2 uv7_m;   // tc7
out vec4 ocol0;

vec2 clamp16(vec2 v){ return clamp(v, vec2(-65504.0), vec2(65504.0)); }
vec3 clamp16(vec3 v){ return clamp(v, vec3(-65504.0), vec3(65504.0)); }
vec4 clamp16(vec4 v){ return clamp(v, vec4(-65504.0), vec4(65504.0)); }

void main()
{
    vec4 r0 = vec4(0.0), r1 = vec4(0.0), r2 = vec4(0.0), r3 = vec4(0.0);
    vec3 h0, h1, h2;

    // tc1 pair
    r0.xyz = texture(tex0, uv1_p).xyz;
    r1.xyz = texture(tex0, uv1_m).xyz;
    h1 = clamp16(r0.xyz + r1.xyz);

    // center tap (tc0) * const0
    r1.xyz = texture(tex0, uv0c).xyz;
    h0 = r1.xyz * vec3(0.254703, 0.138864, 0.184247);

    // tc1 pair * const1
    r1.xyz = texture(tex0, uv2_p).xyz;          // (next pair's + tap, fetched early)
    h0 = clamp16(h1 * vec3(0.21002, 0.130849, 0.166006) + h0);

    // tc2 pair
    r2.xyz = texture(tex0, uv2_m).xyz;
    h1 = clamp16(r1.xyz + r2.xyz);

    r1.xyz = texture(tex0, uv3_p).xyz;
    h0 = clamp16(h1 * vec3(0.117745, 0.109474, 0.121422) + h0);   // tc2 * const2

    // tc3 pair
    r2.xyz = texture(tex0, uv3_m).xyz;
    h1 = clamp16(r1.xyz + r2.xyz);

    r1.xyz = texture(tex0, uv4_p).xyz;
    h0 = clamp16(h1 * vec3(0.0448828, 0.0813223, 0.0720971) + h0); // tc3 * const3

    // tc4 pair
    r2.xyz = texture(tex0, uv4_m).xyz;
    h1 = clamp16(r1.xyz + r2.xyz);

    r1.xyz = texture(tex0, uv5_p).xyz;
    h0 = clamp16(h1 * vec3(0.0, 0.0536375, 0.0347526) + h0);       // tc4 * const4

    // tc5 pair
    r2.xyz = texture(tex0, uv5_m).xyz;
    h1 = clamp16(r1.xyz + r2.xyz);

    r1.xyz = texture(tex0, uv6_p).xyz;
    h0 = clamp16(h1 * vec3(0.0, 0.0314114, 0.0135989) + h0);       // tc5 * const5

    // tc6 pair
    r2.xyz = texture(tex0, uv6_m).xyz;
    h1 = clamp16(r1.xyz + r2.xyz);

    r3.xyz = texture(tex0, uv7_p).xyz;
    h0 = clamp16(h1 * vec3(0.0, 0.016333, 0.0) + h0);              // tc6 * const6

    r0.w = 0.0;   // const7.w

    // tc7 pair
    r1.xyz = texture(tex0, uv7_m).xyz;
    h2 = clamp16(r3.xyz + r1.xyz);

    r0.xyz = h2 * vec3(0.0, 0.00754058, 0.0) + h0;                 // tc7 * const8

    ocol0 = r0;
}

