    // r0.y = dot(r1.xyz, -const3.xyz)  (const3 = {1.4291,1.77865,-0.315622})
    r0.y = dot(r1.xyz, -vec3(1.4291, 1.77865, -0.315622));
    // r1.xyz = fma(r1.xyz, r0.y, const4.xyz)  (const4 = const3)
    r1.xyz = r1.xyz * r0.y + vec3(1.4291, 1.77865, -0.315622);
    // r0.y = dot(r1.xyz, r1.xyz)
    r0.y = dot(r1.xyz, r1.xyz);
    // r1.x = r0.w * const5.x   (const5.x = 1.4427 = 1/ln2)
    r1.x = r0.w * 1.4427;
    // r0.w = divsq(abs(r0.y), r0.y)  ( = |r0.y|/sqrt(|r0.y|) = sqrt(|r0.y|) )
    r0.w = _divsq1(abs(r0.y), r0.y);
    // h0.x = (r0.w >= const6.x) ? 1:0   (const6.x = 1.0)
    h0.x = (r0.w >= 1.0) ? 1.0 : 0.0;
    // r0.y = exp2(r1.x)   ( = exp2( -(abs(rx)*9.40005 + abs(ry)*10.1) * 1.4427 ) )
    r0.y = exp2(r1.x);
    // r1 = r0.y * const7   (const7 = {1,1,1,1})  -> vec4(r0.y)
    r1 = vec4(r0.y);
    // r0 = r1 * h0.x   -> gated falloff in all channels
    r0 = r1 * h0.x;
    // h1.x = r0.z * 8.     (r0.z now == gated falloff)
    h1.x = r0.z * 8.0;
    // r1.zw = r0.xxxy.zw * 8.  -> r1.z = r0.x*8, r1.w = r0.y*8
    r1.z = r0.x * 8.0;
    r1.w = r0.y * 8.0;
    // h1.y = max(r1.z, r1.w)
    h1.y = max(r1.z, r1.w);
    // r0.xy = TEX2D(15, r1.zw)
    r0.xy = texture(tex15, r1.zw).xy;
    // r0.z = TEX2D(14, h1.xy)
    r0.z = texture(tex14, h1.xy).z;

    // col0 = r0 ; ROP rounding/blend handled by pipeline. Additive blend (src=ONE? actually src=770(SRC_ALPHA) dst=1(ONE)).
    ocol0 = r0;
}

